
.panel {
  flex: 1;
  min-width: 260px;
  background: var(--c-card);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
}
.panel-header {
  background: linear-gradient(90deg, rgba(184, 112, 15, 0.35), transparent);
  padding: 8px 10px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  display: flex;
  align-items: center;
  gap: 8px;
}
.panel-dot { font-size: 7px; }
.panel-body { padding: 10px; }

.identity-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.player-name {
  font-size: 15px;
  font-weight: 700;
  color: var(--c-primary);
  font-family: var(--font-display);
  letter-spacing: 1px;
}
.player-meta {
  font-size: 10px;
  color: var(--c-text-muted);
}
.player-position {
  font-size: 11px;
  color: var(--c-text-dim);
  margin-top: 2px;
}

.divider {
  border-top: 1px solid #1e1e1e;
  margin: 8px 0;
}

.rating-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.rating-label {
  font-size: 10px;
  color: var(--c-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.rating-value {
  font-size: 18px;
  font-weight: 700;
  font-family: var(--font-display);
}
.rating-elite { color: #ffd700; text-shadow: 0 0 8px rgba(255, 215, 0, 0.3); }
.rating-good { color: #4caf50; }
.rating-avg { color: #e0e0e0; }
.rating-bad { color: var(--c-danger); }

.career-row {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}
.career-item {
  font-size: 11px;
  color: var(--c-text-muted);
  display: flex;
  align-items: center;
  gap: 3px;
}
.career-icon {
  font-size: 8px;
  color: var(--c-primary);
}
